import {planStudio} from './plan-studio.js';
import {todayRoutines,profileBar,routinePanel,weeklyMarkup,heatControls,heatCounts,heatColor,feedbackMarkup,syncProfile,initFeatures} from './features.js';
import {sessionSequence,measureUnit} from './training-core.js';
import {setVoice,speak,stopVoice} from './voice.js';
import {dashboard,performanceMarkup,lastSet,quickWorkout} from './coach.js';
import {mediaFor,mediaMarkup,playMedia,stopMedia} from './media.js';
import {muscleColors} from './catalog.js';
import {dateKey,streak,motivation,coachingMarkup,learningMarkup,learningGuide,achievementMarkup,celebrate} from './experience.js';
import {photos,muscles,exercises,equipmentNames,goals,plans,available,dayWorkout,levels} from './data.js';
import {currentLocale,translateText,translateTree,chooseInitialLanguage} from './i18n.js';
const $=s=>document.querySelector(s);const app=$('#app'),modal=$('#modal');
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',exercise:'<rect x="3" y="6" width="4" height="12" rx="1.5"/><rect x="17" y="6" width="4" height="12" rx="1.5"/><path d="M7 12h10M1 10v4m22-4v4"/>',atlas:'<circle cx="12" cy="4" r="2"/><path d="M8 9h8m-8 0-3 6m3-6 1 7-2 6m9-13 3 6m-3-6-1 7 2 6M9 16h6m-3-7v7"/>',plan:'<rect x="3" y="5" width="18" height="16" rx="4"/><path d="M8 3v4m8-4v4M3 11h18m-14 5 3 3 6-6"/>',progress:'<path d="M4 3v17a1 1 0 0 0 1 1h16M8 15v2m5-6v6m5-10v10M7 10l5-5 4 1 4-4"/>',cardio:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',mobility:'<path d="M5 12a7 7 0 1 1 2 5m-2-5v6h6"/>'};
const icon=n=>`<span class="nav-icon"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.exercise}</svg></span>`;
const routes=[['home','Ana sayfa'],['exercise','Egzersizler'],['atlas','Kas atlası'],['plan','Planım'],['progress','Gelişimim']];
const defaults={goal:'fit',place:'home',equipment:[],level:'beginner',plan:'balance',onboarded:false,start:new Date().toISOString(),history:[],checkins:[]};
let state;try{state={...defaults,...JSON.parse(localStorage.getItem('forma-v1')||'{}')};if(!Array.isArray(state.equipment)||!Array.isArray(state.history))state={...defaults};}catch{state={...defaults};}
function hasProAccess(){try{const b=JSON.parse(localStorage.getItem('forma-billing')||'{}');return b.status==='active'||(b.status==='trial'&&new Date(b.trialEnd).getTime()>Date.now());}catch{return false;}}
let route=location.hash.slice(1)||'home',filter='all',muscleFilter='all',placeFilter='available',search='',selectedMuscle='chest',selectedDay=0,heatMode=false,atlas=null,draft=null,setupStep=0,session=null,timer=null,toastTimer;
const save=()=>{try{localStorage.setItem('forma-v1',JSON.stringify(state));}catch{toast('Tarayıcı kayıt izni vermedi. Tercihler yalnızca bu oturumda kalacak.');}};
const toast=t=>{$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plan=()=>plans.find(p=>p.id===state.plan)||plans[1];const currentGoal=()=>goals.find(g=>g.id===state.goal)||goals[0];
const dayDate=i=>{const d=new Date(state.start);d.setHours(12,0,0,0);d.setDate(d.getDate()+i);return d;};
const todayIndex=()=>Math.max(0,Math.min(27,Math.floor((new Date().setHours(0,0,0,0)-new Date(state.start).setHours(0,0,0,0))/86400000)));
const finished=i=>state.history.some(h=>h.day===i&&h.start===state.start);
const nextWorkout=()=>{for(let i=todayIndex();i<28;i++)if(!dayWorkout(state,state.plan,i).rest&&!finished(i))return i;return -1;};
const heading=(title,sub,extra='')=>`<div class="heading"><div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`;
function nav(){for(const id of ['#side-nav','#mobile-nav'])$(id).innerHTML=routes.map(([key,label])=>`<a class="nav-link ${route===key?'active':''}" href="#${key}" ${route===key?'aria-current="page"':''}>${icon(key)}<span>${label}</span>${key==='atlas'&&!hasProAccess()?'<small class="nav-pro-badge">PRO</small>':''}</a>`).join('');$('#breadcrumb').textContent=routes.find(r=>r[0]===route)?.[1]||'Genel bakış';$('#date').textContent=new Date().toLocaleDateString(currentLocale(),{day:'numeric',month:'long',year:'numeric'});}
function atlasMarkup(large=false){return `<div class="atlas-card ${large?'atlas-large':''}"><div class="week-title"><span class="eyebrow">VÜCUDUNU TANI</span><span class="badge">3D · ANATOMİ</span></div><h2>Hareketin başladığı yer.</h2><p>Bir kasa dokun, egzersizlerini keşfet.</p><div class="atlas-stage" id="atlas-stage"><div class="atlas-label" id="atlas-label">${muscles[selectedMuscle].name}</div></div><div class="atlas-hint">Sürükle ve döndür · Bir kas seç</div><div class="atlas-controls"><button data-action="rotate" data-value="0">Ön</button><button data-action="rotate" data-value="3.141592653589793">Arka</button><button data-action="zoom" data-value="1" aria-label="Yakınlaştır">＋</button><button data-action="zoom" data-value="-1" aria-label="Uzaklaştır">−</button></div><div class="muscle-selected"><div><strong id="selected-name">${muscles[selectedMuscle].name}</strong><small id="selected-count">${exercises.filter(e=>e.muscle===selectedMuscle||e.secondary.includes(selectedMuscle)).length} egzersizi keşfet</small></div><button class="round-arrow" data-action="muscle-open" aria-label="Seçili kasın egzersizlerini göster">↗</button></div>${large?'<small style="display:block;margin-top:13px;font-size:11px">BodyParts3D + Z-Anatomy · 467 anatomik yapı. Eğitim amaçlıdır; klinik değerlendirme aracı değildir.</small>':''}</div>`;}
function home(){return profileBar(state)+todayRoutines(state)+dashboard(state,{next:nextWorkout(),goal:currentGoal().name,plan:plan(),finished,today:todayIndex(),dayDate,row:exerciseRow})+weeklyMarkup(state);}
function exerciseCard(e){const art=mediaFor(e)?.poster||(e.category==='cardio'?photos.cardio:e.category==='mobility'?photos.yoga:photos.strength);return `<button class="exercise-card" data-action="exercise" data-id="${e.id}"><div class="exercise-art"><img src="${art}" alt="" loading="lazy"><span class="play">${mediaFor(e)?'▶':'↗'}</span></div><div class="exercise-info"><span class="exercise-tag">${muscles[e.muscle].name}</span><h3>${e.name}</h3><div class="meta"><span>${equipmentNames[e.equipment]}</span><span>${e.reps}</span></div></div></button>`;}
function filtered(){const query=search.toLocaleLowerCase(currentLocale());return exercises.filter(e=>(filter==='all'||(filter==='favorites'&&(state.favorites||[]).includes(e.id))||(filter==='native'&&mediaFor(e)?.type==='video')||filter===e.category||(filter==='burn'&&e.category==='cardio'))&&(muscleFilter==='all'||e.muscle===muscleFilter||e.secondary.includes(muscleFilter))&&(placeFilter==='all'||available(state).some(x=>x.id===e.id))&&[e.name,translateText(e.name),muscles[e.muscle]?.name,translateText(muscles[e.muscle]?.name||'')].some(value=>value.toLocaleLowerCase(currentLocale()).includes(query)));}
function library(){return `${heading('Her hareketin bir yolu var.','Hareketi öğren. Kasını tanı. Kontrollü ilerle.',`<span class="badge">${exercises.length} egzersiz</span>`)}<div class="toolbar"><input id="search" type="search" value="${esc(search)}" placeholder="Egzersiz ara…" aria-label="Egzersiz ara"><select id="muscle-filter" aria-label="Kas grubuna göre filtrele"><option value="all">Tüm kas grupları</option>${Object.entries(muscles).map(([k,m])=>`<option value="${k}" ${muscleFilter===k?'selected':''}>${m.name}</option>`).join('')}</select><select id="place-filter" aria-label="Ekipmana göre filtrele"><option value="available" ${placeFilter==='available'?'selected':''}>Ekipmanıma uygun</option><option value="all" ${placeFilter==='all'?'selected':''}>Tüm ekipmanlar</option></select></div><div class="chips">${[['all','Tümü'],['favorites','♡ Favorilerim'],['native','Doğrudan video'],['strength','Kuvvet'],['cardio','Kardiyo'],['burn','Yağ kaybını destekle'],['mobility','Mobilite']].map(([k,l])=>`<button class="chip ${filter===k?'active':''}" data-action="filter" data-value="${k}">${l}</button>`).join('')}</div>${filter==='burn'?'<div class="tip" style="margin-bottom:20px;margin-top:0">Bölgesel yağ yakımı vadetmiyoruz. Bu hareketler enerji harcamasını destekler; kilo değişimi beslenme, uyku ve toplam aktiviteyle ilişkilidir.</div>':''}<div class="library-results-bar"><span id="library-count" role="status">${filtered().length} hareket bulundu</span><button class="text-button" data-action="clear-filters">Filtreleri temizle ↺</button></div><div id="exercise-results" class="exercise-grid">${renderResults()}</div>`;}
function renderResults(){const l=filtered();if($('#library-count'))$('#library-count').textContent=l.length+' hareket bulundu';return l.length?l.map(exerciseCard).join(''):'<div class="empty">Bu seçimle eşleşen hareket yok.<br>Kas veya ekipman filtresini genişletebilirsin.<button class="secondary" data-action="clear-filters">Tüm hareketleri göster ↗</button></div>';}
function muscleRows(){const list=available(state).filter(e=>e.muscle===selectedMuscle||e.secondary.includes(selectedMuscle));return `<span class="eyebrow">SEÇİLİ KAS GRUBU</span><h2 style="font-size:29px;margin-top:9px">${muscles[selectedMuscle].name}</h2><small>${muscles[selectedMuscle].latin}</small><p class="muscle-description">${muscles[selectedMuscle].description}</p><span class="badge">${state.place==='home'?'Ev':'Salon'} · Ekipmanına uygun ${list.length} hareket</span>${list.length?list.map((e,i)=>exerciseRow(e,i)).join(''):'<p class="muscle-description">Bu kas için seçtiğin ekipmanlarla doğrudan bir hareket bulunmuyor. Dambıl veya direnç bandı seçimini tercihlerden düzenleyebilirsin.</p>'}<div class="tip">Listede birincil ve yardımcı olarak bu kas grubunu çalıştıran hareketler bulunur.</div>`;}
function exerciseRow(e,i,sets){return `<button class="exercise-row" data-action="exercise" data-id="${e.id}"><span class="number">${String(i+1).padStart(2,'0')}</span><span><strong>${e.name}</strong><small>${sets&&e.category==='strength'?(e.sets||sets)+' set · ':''}${e.reps} · ${equipmentNames[e.equipment]}</small>${e.adaptation?'<small class="adaptation-inline">'+esc(e.adaptation)+'</small>':''}</span><span class="row-arrow">↗</span></button>`;}
function atlasPage(){return `${heading('Vücudunu keşfet.','23 kas bölgesi · Bölge seç veya anatomiyi döndür.')}<div id="heat-controls">${heatControls(state,heatMode,selectedMuscle)}</div><div class="muscle-list">${Object.entries(muscles).map(([k,m])=>`<button class="chip ${k===selectedMuscle?'active':''}" data-action="muscle" data-value="${k}"><i class="muscle-swatch" style="background:${muscleColors[k]}"></i>${m.name}</button>`).join('')}</div><div class="atlas-layout">${atlasMarkup(true)}<section class="panel" id="muscle-results">${muscleRows()}</section></div>`;}
function calendarDetail(){const w=dayWorkout(state,state.plan,selectedDay);return `<div class="section-heading"><div><h3>${dayDate(selectedDay).toLocaleDateString(currentLocale(),{day:'numeric',month:'long'})} · ${w.title}</h3><small>${w.rest?'İsteğe bağlı kısa yürüyüş ve rahat mobilite.':`${w.minutes} dk · ${w.exercises.length} hareket · ${w.week+1}. hafta`}</small></div>${!w.rest?`<button class="primary" data-action="start" data-day="${selectedDay}" ${finished(selectedDay)||w.missingEquipment?.length?'disabled':''}>${finished(selectedDay)?'✓ Tamamlandı':'Başla ↗'}</button>`:''}</div>${w.rest?'<div class="tip">Dinlenme günü. Zorlayıcı antrenman yerine rahat hissettiren hafif hareketleri tercih et.</div>':w.exercises.map((e,i)=>exerciseRow(e,i,w.sets)).join('')}`;}
function planPage(){return planStudio(state,{selectedDay,today:todayIndex(),next:nextWorkout(),dayDate,profileBar,routinePanel,detail:calendarDetail});}
function planPreview(id){const p=plans.find(p=>p.id===id);if(!p)return;const active=p.id===state.plan;openModal('<div class="modal-content">'+modalTop(p.name)+'<p class="muted">'+p.desc+'</p><div class="plan-preview-stats"><div><strong>'+p.days+'</strong><small>gün / hafta</small></div><div><strong>≈'+p.minutes+'</strong><small>dakika / seans</small></div><div><strong>'+p.days*4+'</strong><small>planlı seans</small></div></div><div class="tip">'+(active?'Bu plan şu anda aktif. Takvimini aşağıda inceleyebilirsin.':state.activeSession?'Kaydedilmiş bir seansın var. Planını değiştirmeden önce bu seansı tamamla.':'Bu planı seçince bugün başlayan yeni bir dört haftalık takvim oluşturulur. Geçmiş seansların gelişim günlüğünde saklanır.')+'</div><div class="plan-preview-actions"><button class="secondary" data-action="close">'+(active?'Planıma dön':'Mevcut planımı koru')+'</button>'+(!active&&!state.activeSession?'<button class="primary" data-action="plan-confirm" data-value="'+p.id+'">Yeni planı başlat ↗</button>':'')+'</div></div>');}
function selectPlanDay(day,focus){selectedDay=Math.max(0,Math.min(27,Number(day)||0));render();if(focus)document.querySelector(focus)?.focus({preventScroll:true});}
function progressPage(){const history=state.history.filter(h=>h.start===state.start&&h.day>=0),pct=Math.min(100,Math.round(history.length/(plan().days*4)*100));return `${heading('Dünden bir adım ileride.','İlerlemenin tek ölçüsü görünüşün değil, devam etmen.')}${weeklyMarkup(state)}${performanceMarkup(state)}${motivation(state)}${achievementMarkup(state)}<div class="progress-grid"><section class="panel center"><span class="eyebrow">AYLIK PLAN</span><div class="progress-ring" style="--progress:${pct}%"><strong>%${pct}</strong></div><h2>${history.length} antrenman tamamlandı</h2><p class="muted" style="font-size:14px;margin:12px 0">${plan().days*4} seanslık ${plan().name} planın</p><a class="primary" href="#plan">Planıma dön ↗</a></section><section class="panel"><h2>Hareket günlüğün</h2>${state.history.length?state.history.slice().reverse().map(h=>`<div class="history-row"><div>${esc(h.title)}<small>${new Date(h.date).toLocaleDateString(currentLocale(),{day:'numeric',month:'long'})} · ${h.minutes} dk</small></div><span class="green">✓</span></div>${feedbackMarkup(state.history.indexOf(h),h.feedback)}${h.logs?.length?`<details class="guide-detail"><summary>Set kayıtlarını gör · ${h.logs.length} set</summary>${h.logs.map(l=>`<p>${esc(exercises.find(e=>e.id===l.exercise)?.name||l.exercise)} · Set ${l.set}${l.amount!==null?` · ${l.amount} ${esc(l.unit)}`:""}${l.load!==null?` · ${l.load} kg`:""}</p>`).join("")}</details>`:""}`).join(''):'<div class="empty" style="margin-top:20px">Henüz tamamlanan antrenmanın yok.<br>İlk seansından sonra günlüğün burada oluşacak.</div>'}<p class="muted" style="font-size:12px;margin-top:20px">Tercihlerin ve günlüğün yalnızca bu tarayıcıda tutulur. Cihazlar arası eşitleme yoktur.</p></section></div>`;}
async function render(){atlas?.dispose();atlas=null;if(!routes.some(r=>r[0]===route))route='home';if(route==='atlas'&&!hasProAccess()){route='home';history.replaceState(null,'','#home');setTimeout(()=>window.FORMA_BILLING?.requestPro('atlas'),0);}nav();app.innerHTML=`<div class="page">${({home,exercise:library,atlas:atlasPage,plan:planPage,progress:progressPage}[route])()}${route==='home'?learningMarkup(state):''}</div>`;translateTree(app);if($('#atlas-stage')){const stage=$('#atlas-stage');try{const {createAtlas}=await import('./atlas.js');if(!stage.isConnected)return;atlas=createAtlas(stage,selectedMuscle,selectMuscle);if(heatMode)atlas.setHeat(heatCounts(state));}catch(e){stage.insertAdjacentHTML('beforeend','<div class="empty">3B görünüm yüklenemedi. Kas atlası ekranındaki kas düğmeleriyle egzersizlere ulaşabilirsin.</div>');}}}
function navigate(to){if(to==='atlas'&&!hasProAccess()){window.FORMA_BILLING?.requestPro('atlas');return;}if(route===to)render();else location.hash=to;}
let transition;
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'home';if(next==='atlas'&&!hasProAccess()){history.replaceState(null,'','#'+route);window.FORMA_BILLING?.requestPro('atlas');return;}route=next;window.dispatchEvent(new window.CustomEvent('fitness:eligible-action',{detail:{source:'navigation'}}));const update=()=>{render();window.scrollTo({top:0,behavior:'instant'});};if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches){transition?.skipTransition();transition=document.startViewTransition(update);}else update();});
document.addEventListener('pointerdown',ev=>{const b=ev.target.closest('button.primary,button.secondary,button.chip,.atlas-controls button');if(!b||b.disabled||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=b.getBoundingClientRect(),p=document.createElement('span');p.className='touch-wave';p.style.left=(ev.clientX-r.left)+'px';p.style.top=(ev.clientY-r.top)+'px';p.setAttribute('aria-hidden','true');b.appendChild(p);setTimeout(()=>p.remove(),600);});
function selectMuscle(k){if(!muscles[k])return;selectedMuscle=k;atlas?.select(k);if($('#heat-controls'))$('#heat-controls').innerHTML=heatControls(state,heatMode,k);if($('#atlas-label'))$('#atlas-label').textContent=muscles[k].name;if($('#selected-name'))$('#selected-name').textContent=muscles[k].name;if($('#selected-count'))$('#selected-count').textContent=exercises.filter(e=>e.muscle===k||e.secondary.includes(k)).length+' egzersizi keşfet';if($('#muscle-results'))$('#muscle-results').innerHTML=muscleRows();document.querySelectorAll('[data-action="muscle"]').forEach(b=>b.classList.toggle('active',b.dataset.value===k));}
function openModal(html){stopMedia();$('#modal-body').innerHTML=html;translateTree($('#modal-body'));if(!modal.open)modal.showModal();modal.scrollTop=0;}
const modalTop=(t,closable=true)=>`<div class="modal-top"><h2>${t}</h2>${closable?'<button class="close" data-action="close" aria-label="Kapat">×</button>':''}</div>`;
function setup(step=0){setupStep=step;if(!draft)draft={...state,equipment:[...state.equipment]};let html='';if(step===0)html=`${modalTop('Fitness Copilot’a hoş geldin.')}<img class="onboard-visual" src="${photos.active}" alt="Açık havada koşan sporcu"><span class="eyebrow">BAŞLAMADAN ÖNCE · 1 DAKİKA</span><div class="steps-list"><div class="step-item"><b>01</b><div>Önce hareketi öğren.<small>Her egzersizde adımlar ve form ipuçları var. Hafif başla, nefesini tutma.</small></div></div><div class="step-item"><b>02</b><div>Vücudunun sesini dinle.<small>Önce 5 dakika rahat hareketle ısın. Keskin ağrıda dur; dinlenme günlerine yer aç.</small></div></div><div class="step-item"><b>03</b><div>Kendi hedefini seç.<small>Ev veya salon, elindeki ekipman ve seviyen planını şekillendirsin.</small></div></div></div><p class="muted" style="font-size:12px;margin-bottom:20px">Planlar 18 yaş ve üzeri sağlıklı yetişkinlere yönelik genel örneklerdir. Yaralanma veya egzersizi etkileyen bir sağlık durumunda uzmanla kişiselleştir.</p><button class="primary full" data-action="setup-next">Hedefimi seçeyim <span>↗</span></button><button class="quiet full" data-action="close">Önce uygulamayı keşfet</button>`;
if(step===1)html=`${modalTop('Nasıl hissetmek istiyorsun?')}<div class="setup-line">01 / 03 · Hedefin</div><p class="muted" style="font-size:14px">Sana en yakın hedefi seç. Fotoğraflar ilham içindir; belirli bir vücut görünümü veya sonuç vadetmez.</p><div class="goal-grid">${goals.map(g=>`<button class="goal-option ${draft.goal===g.id?'selected':''}" data-action="goal" data-value="${g.id}" aria-pressed="${draft.goal===g.id}"><img src="${photos[g.image]}" alt="${g.name} için aktivite görseli"><span><strong>${g.name}</strong><small>${g.sub}</small></span></button>`).join('')}</div><div class="onboard-actions"><button class="secondary" data-action="setup-back">Geri</button><button class="primary" data-action="setup-next">Devam et ↗</button></div>`;
if(step===2)html=`${modalTop('Antrenman alanın neresi?')}<div class="setup-line">02 / 03 · Alanın ve ekipmanın</div><div class="choice-grid">${[['home','⌂ Evde','Kendi alanında, kendi ritminde.'],['gym','◇ Spor salonunda','Makine ve serbest ağırlıklarla.']].map(([k,t,s])=>`<button class="choice ${draft.place===k?'selected':''}" data-action="place" data-value="${k}" aria-pressed="${draft.place===k}"><strong>${t}</strong><small>${s}</small></button>`).join('')}</div><h3>Hangi ekipmanlar var?</h3><small>Hiçbirini seçmezsen ekipmansız hareketler verilir.</small><div class="equipment-actions"><button class="text-button" data-action="equipment-all">Tümünü seç</button><button class="quiet" data-action="equipment-none">Seçimi temizle</button><span id="equipment-count">${draft.equipment.length} seçili</span></div><div class="equipment">${Object.entries(equipmentNames).filter(([k])=>k!=='none'&&(draft.place==='gym'||['dumbbells','band','bench','inclinebench','kettlebell','step'].includes(k))).map(([k,l])=>`<label class="check-choice"><input type="checkbox" value="${k}" class="equipment-check" ${draft.equipment.includes(k)?'checked':''}>${l}</label>`).join('')}</div><div class="onboard-actions"><button class="secondary" data-action="setup-back">Geri</button><button class="primary" data-action="setup-next">Devam et ↗</button></div>`;
if(step===3)html=`${modalTop('Bir ritim seçelim.')}<div class="setup-line">03 / 03 · Seviyen</div><h3>Egzersiz deneyimin</h3><select class="level-select" id="level-select"><option value="beginner" ${draft.level==='beginner'?'selected':''}>Yeni başlıyorum / uzun ara verdim</option><option value="intermediate" ${draft.level==='intermediate'?'selected':''}>Düzenli egzersiz yapıyorum</option><option value="advanced" ${draft.level==='advanced'?'selected':''}>İleri seviye · Deneyimli antrenman</option></select><div class="tip"><div><strong>${goals.find(g=>g.id===draft.goal).name}</strong>${draft.place==='home'?'Evde':'Salonda'} · ${draft.equipment.length?draft.equipment.map(k=>equipmentNames[k]).join(', '):'Ekipmansız'}<br>Sonraki ekranda 4 farklı aylık plan arasından seçim yapabilirsin.</div></div><p class="muted" style="font-size:13px;margin-top:18px">Tercihlerin bu cihazda saklanır. ${state.onboarded?'Kaydedince bugün başlayan yeni bir dört haftalık plan oluşturulur. Geçmiş seansların günlüğünde kalır.':''}</p><div class="onboard-actions"><button class="secondary" data-action="setup-back">Geri</button><button class="primary" data-action="setup-finish">Planlarımı göster ↗</button></div>`;openModal(`<div class="modal-content">${html}</div>`);}
function exerciseDetail(id){stopVoice();const e=exercises.find(e=>e.id===id);if(!e)return;openModal(`<div class="modal-content">${modalTop(e.name)}<span class="eyebrow">${muscles[e.muscle].name}</span><div class="detail-chips"><span>${equipmentNames[e.equipment]}</span><span>${e.reps}</span><span>${e.category==='cardio'?'Kardiyo':e.category==='mobility'?'Mobilite':'Kuvvet'}</span></div>${mediaMarkup(e)}<div class="favorite-toggle"><span>Hareket kütüphanen</span><button class="secondary" data-action="favorite" data-id="${e.id}" aria-pressed="${(state.favorites||[]).includes(e.id)}">${(state.favorites||[]).includes(e.id)?'♥ Kaydedildi':'♡ Favoriye ekle'}</button></div><h3 style="margin-top:22px">Adım adım, doğru form</h3><ol class="instructions">${e.steps.map(t=>'<li>'+t+'</li>').join('')}</ol>${coachingMarkup(e)}<button class="secondary full" style="margin-top:20px" data-action="${session?'session-return':'close'}">${session?'Antrenmana dön':'Anladım'}</button></div>`);}
function persistSession(){if(session){state.activeSession={...session,workout:{...session.workout,exercises:session.workout.exercises.map(e=>({id:e.id,sets:e.sets,reps:e.reps,pairNext:e.pairNext,suggestedLoad:e.suggestedLoad,adaptation:e.adaptation}))}};}else delete state.activeSession;save();}
function resumeSession(){const saved=state.activeSession;if(!saved)return;const list=saved.workout?.exercises?.map(item=>{const e=exercises.find(e=>e.id===(typeof item==='string'?item:item.id));return e?{...e,...(typeof item==='string'?{}:item)}:null;}).filter(Boolean)||[];if(!list.length||saved.index>=list.length){delete state.activeSession;save();render();return;}session={...saved,workout:{...saved.workout,exercises:list},started:Date.now()-(saved.elapsedMs||0),rest:0};session.sequence=session.sequence||sessionSequence(session.workout);session.position=session.position??Math.max(0,session.sequence.findIndex(x=>x.index===session.index&&x.set===session.set));showSession();}
function startSession(day,custom=null){if(state.activeSession&&!session){resumeSession();return;}if(!custom&&(day<0||day>27))return;const w=custom||dayWorkout(state,state.plan,day);if(w.missingEquipment?.length){toast('Önce programına uygun ekipman alanını seç.');return;}if(w.rest||(!custom&&finished(day)))return;clearInterval(timer);session={day,planStart:state.start,workout:w,index:0,set:1,started:Date.now(),elapsedMs:0,logs:[],rest:0,restDuration:state.restDuration||60,input:{},sequence:w.sequence||sessionSequence(w),position:0};persistSession();showSession();}
function pauseSession(){if(!session)return;stopVoice();session.elapsedMs=Date.now()-session.started;session.rest=0;clearInterval(timer);persistSession();session=null;modal.close();render();toast('Seansın saklandı. Ana ekrandan devam edebilirsin.');}
function showSession(){if(!session)return;const s=session,e=s.workout.exercises[s.index],count=s.workout.exercises.length,previous=lastSet(state,e.id),done=s.logs.filter(l=>l.exercise===e.id);openModal(`<div class="modal-content session-focus">${modalTop('Odak modu')}<div class="session-topline"><span class="eyebrow">${esc(s.workout.title)}</span><span class="mini-pill">${s.index+1} / ${count} hareket</span></div><div class="session-meter"><div style="width:${(s.position||0)/s.sequence.length*100}%"></div></div><h2>${e.name}</h2><p class="center muted">${e.reps} · ${equipmentNames[e.equipment]}</p>${e.adaptation?'<div class="adaptation-note"><strong>Bu seansın önerisi</strong><p>'+esc(e.adaptation)+'</p>'+(e.suggestedLoad!=null?'<small>Yük referansı: '+e.suggestedLoad+' kg · Zorunlu hedef değil</small>':'')+'</div>':''}<div class="session-count" id="rest-count">${s.rest?s.rest:s.set}<small style="font-size:16px">${s.rest?' sn':e.category==='strength'?' / '+(e.sets||s.workout.sets)+' set':' / '+(e.sets||1)+' tur'}</small></div><p class="center muted" id="session-instruction">${s.rest?'Nefesini düzenle. Bir sonraki sete hazırlan.':'Kontrollü başla. Her tekrarını sahiplen.'}</p>${previous?`<div class="last-set">↗ Son kaydın: ${previous.amount} ${esc(previous.unit)}${previous.load!=null?' · '+previous.load+' kg':''}</div>`:''}${!s.rest?`<div class="set-inputs"><label>${measureUnit(e)==='sn'?'Süre (saniye)':measureUnit(e)==='dk'?'Süre (dakika)':'Yaptığın tekrar'}<input id="set-reps" type="number" min="1" max="999" inputmode="numeric" value="${esc(s.input?.reps||'')}" placeholder="—"></label>${e.category==='strength'&&e.equipment!=='none'?`<label>Yük (kg)<input id="set-load" type="number" min="0" max="1500" step="0.5" inputmode="decimal" value="${esc(s.input?.load||'')}" placeholder="—"></label>`:''}</div>`:''}${done.length?`<div class="session-log">${done.map(l=>`<span>✓ Set ${l.set}${l.amount!=null?' · '+l.amount+' '+esc(l.unit):''}${l.load!=null?' · '+l.load+' kg':''}</span>`).join('')}</div>`:''}<button class="voice-toggle secondary full" data-action="voice-toggle" aria-pressed="${!!state.voiceGuide}">${state.voiceGuide?'♫ Sesli rehber açık':'♫ Sesli rehberi aç'}</button><small class="voice-note">Ses, tarayıcı desteğiyle ve ekran açıkken çalışır.</small><div class="rest-presets"><span>Set arası dinlenme</span>${[45,60,90,120].map(n=>`<button data-action="rest-duration" data-value="${n}" aria-pressed="${s.restDuration===n}">${n}s</button>`).join('')}</div><div class="session-tasks"><button class="secondary" data-action="exercise" data-id="${e.id}">▶ Video ve teknik</button><button class="secondary" data-action="swap-open">⇄ Alternatif seç</button></div><button class="primary full" style="margin-top:16px" id="session-next" data-action="session-next" ${s.rest?'disabled':''}>${s.rest?'Dinlenme sürüyor':e.category==='strength'?'Seti tamamladım ✓':'Hareketi tamamladım ✓'}</button>${s.rest?'<button class="quiet full" data-action="rest-skip">Dinlenmeyi bitir</button>':''}<button class="quiet full" data-action="session-exit">Kaydet ve sonra devam et</button></div>`);announceSession();}
let spokenSet='';
function announceSession(){if(!session||session.rest)return;const key=session.started+':'+session.index+':'+session.set;if(key===spokenSet)return;spokenSet=key;const e=session.workout.exercises[session.index];speak(e.name+'. Set '+session.set+'. Hedef '+e.reps+'. Kontrollü başla.');}
function restFor(seconds){session.rest=seconds;persistSession();showSession();speak(seconds+' saniye dinlen.');const until=Date.now()+seconds*1000;let warned=false;clearInterval(timer);timer=setInterval(()=>{if(!session){clearInterval(timer);return;}session.rest=Math.max(0,Math.ceil((until-Date.now())/1000));if(!warned&&session.rest<=10&&session.rest>0){warned=true;speak('Dinlenmenin bitmesine on saniye.');}if($('#rest-count'))$('#rest-count').innerHTML=session.rest+'<small style="font-size:16px"> sn</small>';if(!session.rest){clearInterval(timer);persistSession();showSession();}},250);}
function nextSet(){if(!session||session.rest)return;const e=session.workout.exercises[session.index],reps=$('#set-reps'),load=$('#set-load');if((reps&&!reps.checkValidity())||(load&&!load.checkValidity())){toast('Geçerli bir tekrar, süre veya yük gir.');return;}session.logs.push({exercise:e.id,set:session.set,amount:reps?.value?Number(reps.value):null,load:load?.value?Number(load.value):null,unit:measureUnit(e)});session.input={};session.elapsedMs=Date.now()-session.started;const step=session.sequence[session.position];session.position++;if(session.position>=session.sequence.length){const minutes=Math.max(1,Math.round((Date.now()-session.started)/60000)),sets=session.logs.length;state.history.push({day:session.day,start:session.planStart,date:new Date().toISOString(),title:session.workout.title,minutes,logs:session.logs,routineId:session.workout.routineId,feedback:null});session=null;delete state.activeSession;save();clearInterval(timer);speak('Antrenman tamamlandı. Emeğine sağlık.');celebrate();render();openModal(`<div class="modal-content center">${modalTop('Bugünlük sözünü tuttun.')}<div class="session-count">✓</div><h2>${sets} set. Kendin için.</h2><p class="muted">+50 XP · ${minutes} dakika · Kaydedildi.</p>${feedbackMarkup(state.history.length-1,null)}<button class="primary full" data-action="finish-progress">Gelişimimi gör ↗</button></div>`);return;}const next=session.sequence[session.position];session.index=next.index;session.set=next.set;persistSession();if(step.restAfter)restFor(session.restDuration);else showSession();}
initFeatures({state:()=>state,save,render,open:openModal,top:modalTop,close:()=>modal.close(),toast,start:startSession,heat:()=>{heatMode=true;navigate('atlas');}});setVoice(!!state.voiceGuide,toast);
let pendingQuick=null;
function quickPreview(minutes){pendingQuick=quickWorkout(state,minutes);openModal('<div class="modal-content">'+modalTop(pendingQuick.title)+'<p class="muted">Yaklaşık süre; tempona ve dinlenmene göre değişir. Öncesinde 5 dakika rahat hareketle ısın. Her kuvvet hareketi 2 set.</p>'+pendingQuick.exercises.map((e,i)=>exerciseRow(e,i,2)).join('')+'<button class="primary full" data-action="quick-start">Bu seansa başla ↗</button></div>');}
function swapOpen(){if(!session||session.rest){toast('Alternatifi dinlenme bittikten sonra seçebilirsin.');return;}const e=session.workout.exercises[session.index];if(session.set>1){toast('Alternatif hareketi ilk sete başlamadan seç.');return;}const list=available(state).filter(x=>x.id!==e.id&&x.category===e.category&&x.muscle===e.muscle&&!session.workout.exercises.some(y=>y.id===x.id));openModal('<div class="modal-content">'+modalTop('Ekipman doluysa, plan devam eder.')+'<p class="muted">Aynı ana kas grubuna ve seçtiğin ekipmanlara uygun seçenekler. Hareketlerin yük ve zorlukları eşdeğer değildir.</p>'+(list.length?list.map(x=>'<button class="exercise-row" data-action="swap" data-id="'+x.id+'"><span><strong>'+x.name+'</strong><small>'+equipmentNames[x.equipment]+' · '+x.reps+'</small></span><span>⇄</span></button>').join(''):'<p class="tip">Bu ekipman seçimiyle başka uygun hareket yok. Mevcut hareketini koruyabilirsin.</p>')+'<button class="secondary full" data-action="session-return">Seansıma dön</button></div>');}

function sources(){openModal(`<div class="modal-content">${modalTop('Kaynaklar ve Fitness Copilot hakkında')}<p class="muted" style="font-size:14px;margin-bottom:20px">Fitness Copilot, mobil tarayıcıda çalışan bir fitness prototipidir. Ana ekrana ekleyerek uygulama görünümünde kullanabilirsin. 3B atlas, BodyParts3D ve Z-Anatomy kaynaklı gerçek anatomik yüzeylerden oluşur.</p><div class="source-links"><a href="https://www.cdc.gov/physical-activity-basics/guidelines/adults.html" target="_blank" rel="noopener">CDC · Yetişkinler için fiziksel aktivite rehberi ↗</a><a href="https://www.acefitness.org/resources/everyone/exercise-library/" target="_blank" rel="noopener">ACE · Egzersiz kütüphanesi ↗</a><a href="https://www.nasm.org/resource-center/exercise-library" target="_blank" rel="noopener">NASM · Hareket rehberleri ↗</a></div><p class="muted" style="font-size:13px;margin:20px 0">Genel aktivite rehberleri haftada en az 150 dakika orta tempolu aktivite ve en az iki gün kuvvet çalışması önerir. Fitness Copilot planları bir başlangıç şablonudur; haftanın tüm hareket ihtiyacını tek başına karşıladığı varsayılmaz.</p><h3>Gerçek anatomi modeli</h3><p class="muted" style="font-size:13px;margin:10px 0">BodyParts3D © The Database Center for Life Science · CC BY-SA 2.1 Japan. Z-Anatomy, Gauthier Kervyn · CC BY-SA 4.0. Model hazırlığı: BodyExplorer.</p><div class="source-links"><a href="assets/ATTRIBUTION.txt" target="_blank">Model kaynakları ve lisansları</a><a href="https://ymove.app/free-exercise-videos" target="_blank" rel="noopener">Your Move · MP4 klipleri ve kullanım lisansı</a><a href="https://help.trainingpeaks.com/hc/en-us/article_attachments/32563775872653" target="_blank" rel="noopener">TrainingPeaks · Harekete özel video kaynakları</a></div><h3 style="margin-top:20px">Videolar</h3><p class="muted" style="font-size:13px;margin:10px 0">NASM, ACEfitness, ScottHermanFitness, BarBend, Melbourne Üniversitesi, MFine, Drugs.com, PureGym ve [P]rehab kaynaklı videolar; ayrıca Your Move doğrudan klipleri ve DVIDS oynatıcısı. Hareketin kaynağına göre uygulama içi video veya gömülü oynatıcı kullanılır. Telif hakları sahiplerinde kalır. Bağlantı kullanmak içeriği telifsiz yapmaz.</p><h3>Tasarım referansları</h3><div class="source-links"><a href="https://developer.apple.com/design/human-interface-guidelines/workouts" target="_blank" rel="noopener">Apple · Antrenman deneyimi ilkeleri</a><a href="https://motion.dev/docs/animate" target="_blank" rel="noopener">Motion · Geçiş ve etkileşim referansları</a></div><div class="source-links"><a href="https://uiverse.io/buttons" target="_blank" rel="noopener">Uiverse · Buton etkileşim örnekleri</a><a href="https://m3.material.io/styles/motion/overview/how-it-works" target="_blank" rel="noopener">Material Design · Hareket yaklaşımı</a><a href="https://developer.chrome.com/docs/web-platform/view-transitions/same-document" target="_blank" rel="noopener">Chrome · Ekran geçişleri</a></div><h3>Fotoğraflar</h3><div class="source-links" style="margin:12px 0"><a href="https://www.pexels.com/photo/man-exercising-at-a-gym-4164756/" target="_blank" rel="noopener">Ivan S · Kuvvet</a><a href="https://www.pexels.com/photo/woman-running-on-treadmill-in-gym-31914336/" target="_blank" rel="noopener">Wendell Stoyer · Kardiyo</a><a href="https://www.pexels.com/photo/a-happy-woman-jogging-on-a-sidewalk-during-the-day-8769384/" target="_blank" rel="noopener">Gustavo Fring · Koşu</a><a href="https://www.pexels.com/photo/woman-doing-yoga-6696961/" target="_blank" rel="noopener">Tim Samuel · Yoga</a><a href="https://www.pexels.com/license/" target="_blank" rel="noopener">Pexels kullanım lisansı ↗</a></div><p class="muted" style="font-size:12px">Fotoğraflar hareket tekniği referansı değildir. Tercihlerin ve geçmişin bu tarayıcıda saklanır; video, fotoğraf ve yazı tipi sağlayıcıları çevrimiçi bağlantı gerektirir.</p></div>`);}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,v=b.dataset.value,id=b.dataset.id;switch(a){
case 'level-change':if(levels.some(l=>l.id===v)&&!state.activeSession){state.level=v;save();render();toast('Program seviyesi güncellendi.');}break;
case 'plan-options':{const options=$('#plan-options');options.open=true;options.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});options.querySelector('summary').focus({preventScroll:true});break;}
case 'plan-preview':planPreview(v);break;
case 'plan-confirm':if(plans.some(p=>p.id===v)&&!state.activeSession){state.plan=v;state.start=new Date().toISOString();selectedDay=0;save();modal.close();render();toast('Yeni dört haftalık planın hazır.');}break;
case 'plan-week':selectPlanDay(Number(b.dataset.week)*7,'#plan-week-'+b.dataset.week);break;
case 'plan-today':selectPlanDay(todayIndex(),'[data-action="day"][data-day="'+todayIndex()+'"]');break;
case 'plan-jump':selectPlanDay(b.dataset.day,'[data-action="day"][data-day="'+b.dataset.day+'"]');$('#plan-detail')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});break;
case 'plan-muscle':selectedMuscle=v;navigate('atlas');break;
case 'clear-filters':filter='all';muscleFilter='all';placeFilter='all';search='';render();$('#search')?.focus();break;
case 'close':modal.close();break;
case 'heat-toggle':heatMode=!heatMode;render();break;
case 'voice-toggle':state.voiceGuide=setVoice(!state.voiceGuide,toast);save();spokenSet='';showSession();break;
case 'energy':state.wellness={date:dateKey(),energy:v};save();render();toast('Bugünkü enerji tercihin kaydedildi.');break;
case 'open-atlas':navigate('atlas');break;
case 'rewards':openModal('<div class="modal-content">'+modalTop('Her gelişinde bir adım daha.')+motivation(state)+achievementMarkup(state)+'<p class="muted">Giriş: 10 XP · Tamamlanan seans: 50 XP. Her 250 XP yeni bir seviye. Dinlenme günlerinde antrenman yapmak gerekmez.</p></div>');break;
case 'favorite':state.favorites=Array.isArray(state.favorites)?state.favorites:[];state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();b.textContent=state.favorites.includes(id)?'♥ Kaydedildi':'♡ Favoriye ekle';b.setAttribute('aria-pressed',String(state.favorites.includes(id)));if(route==='exercise'&&filter==='favorites')$('#exercise-results').innerHTML=renderResults();break;
case 'resume':resumeSession();break;
case 'quick':quickPreview(Number(v));break;
case 'quick-start':if(pendingQuick)startSession(-1,pendingQuick);break;
case 'swap-open':swapOpen();break;
case 'swap':if(session){const replacement=available(state).find(e=>e.id===id);if(replacement){session.workout.exercises[session.index]={...replacement,sets:session.workout.exercises[session.index].sets,pairNext:session.workout.exercises[session.index].pairNext};session.input={};persistSession();showSession();}}break;
case 'rest-duration':state.restDuration=Number(v);if(session){session.restDuration=Number(v);persistSession();showSession();}else save();break;case 'setup':draft=null;setup(state.onboarded?1:0);break;case 'setup-next':setup(setupStep+1);break;case 'setup-back':setup(setupStep-1);break;case 'goal':draft.goal=v;setup(1);break;case 'place':draft.place=v;draft.equipment=draft.equipment.filter(k=>v==='gym'||['dumbbells','band','bench','inclinebench','kettlebell','step'].includes(k));setup(2);break;case 'setup-finish':state={...state,...draft,onboarded:true,start:new Date().toISOString()};syncProfile(state);save();draft=null;selectedDay=0;modal.close();navigate('plan');toast('Hedefine uygun plan seçeneklerin hazır.');window.dispatchEvent(new window.CustomEvent('fitness:onboarding-complete'));break;case 'sources':sources();break;case 'learning':openModal('<div class="modal-content">'+modalTop('Gelişim rehberi')+learningGuide()+'</div>');break;case 'equipment-all':draft.equipment=Object.keys(equipmentNames).filter(k=>k!=='none'&&(draft.place==='gym'||['dumbbells','band','bench','inclinebench','kettlebell','step'].includes(k)));setup(2);break;case 'equipment-none':draft.equipment=[];setup(2);break;case 'category':filter=v;muscleFilter='all';navigate('exercise');break;case 'filter':filter=v;render();break;case 'exercise':modal.dataset.adAfter='exercise';exerciseDetail(id);break;case 'video':playMedia(exercises.find(e=>e.id===id),b.dataset.mode);break;case 'muscle':selectMuscle(v);break;case 'muscle-open':if(route!=='atlas')navigate('atlas');else $('#muscle-results').scrollIntoView({behavior:'smooth',block:'start'});break;case 'rotate':atlas?.rotate(Number(v));break;case 'zoom':atlas?.zoom(Number(v));break;case 'plan':planPreview(v);break;case 'day':selectPlanDay(b.dataset.day,'[data-action="day"][data-day="'+b.dataset.day+'"]');break;case 'day-open':selectedDay=Number(b.dataset.day);navigate('plan');break;case 'start':startSession(Number(b.dataset.day));break;case 'session-return':showSession();break;case 'session-next':nextSet();break;case 'rest-skip':clearInterval(timer);session.rest=0;showSession();break;case 'session-exit':pauseSession();break;case 'finish-progress':modal.close();navigate('progress');break;}});
document.addEventListener('input',ev=>{if(ev.target.id==='search'){search=ev.target.value;$('#exercise-results').innerHTML=renderResults();}});
document.addEventListener('change',ev=>{const t=ev.target;if(t.id==='muscle-filter'){muscleFilter=t.value;$('#exercise-results').innerHTML=renderResults();}if(t.id==='place-filter'){placeFilter=t.value;$('#exercise-results').innerHTML=renderResults();}if(t.classList.contains('equipment-check')){draft.equipment=[...modal.querySelectorAll('.equipment-check:checked')].map(x=>x.value);$('#equipment-count').textContent=draft.equipment.length+' seçili';}if(t.id==='level-select')draft.level=t.value;});
modal.addEventListener('close',()=>{stopVoice();stopMedia();const adAfter=modal.dataset.adAfter;delete modal.dataset.adAfter;if(session){session.elapsedMs=Date.now()-session.started;session.rest=0;persistSession();session=null;clearInterval(timer);render();toast('Seansın saklandı. Ana ekrandan devam edebilirsin.');}$('#modal-body').innerHTML='';if(adAfter)window.dispatchEvent(new window.CustomEvent('fitness:eligible-action',{detail:{source:adAfter}}));});
window.addEventListener('pagehide',()=>{if(session){session.elapsedMs=Date.now()-session.started;persistSession();}});
document.addEventListener('input',ev=>{if(session&&['set-reps','set-load'].includes(ev.target.id)){session.input=session.input||{};session.input[ev.target.id==='set-reps'?'reps':'load']=ev.target.value;session.elapsedMs=Date.now()-session.started;persistSession();}});
if(!state.onboarded)await chooseInitialLanguage();
selectedDay=todayIndex();
state.checkins=Array.isArray(state.checkins)?state.checkins:[];const newVisit=!state.checkins.includes(dateKey());if(newVisit){state.checkins.push(dateKey());save();}await render();if(!state.onboarded)setup(0);else if(newVisit)toast('🔥 Yeni bir gün, kendin için yeni bir adım. +10 XP');
if(document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'show_muscle_exercises',title:'Kasın egzersizlerini göster',description:'Kas atlasını açar, belirtilen kası seçer ve mevcut ekipmana uygun egzersizlerini gösterir.',inputSchema:{type:'object',properties:{muscle:{type:'string',enum:Object.keys(muscles)}},required:['muscle'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(!input||typeof input!=='object'||Object.keys(input).length!==1||!Object.hasOwn(muscles,input.muscle))throw new Error('Geçerli bir kas grubu belirtin.');selectedMuscle=input.muscle;route='atlas';history.replaceState(null,'','#atlas');await render();return{muscle:selectedMuscle,exercises:available(state).filter(e=>e.muscle===selectedMuscle||e.secondary.includes(selectedMuscle)).map(e=>({id:e.id,name:e.name}))};}});}catch{ /* Optional browser capability; the visible atlas remains available. */ }}

document.addEventListener('keydown',ev=>{const tab=ev.target.closest('[data-action="plan-week"]');if(!tab||!['ArrowRight','ArrowLeft','Home','End'].includes(ev.key))return;ev.preventDefault();const i=Number(tab.dataset.week),n=ev.key==='Home'?0:ev.key==='End'?3:(i+(ev.key==='ArrowRight'?1:3))%4;selectPlanDay(n*7,'#plan-week-'+n);});
